'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const icons=solarIcons;
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const cats=['Все','iPhone','Mac','iPad','Watch','AirPods'];
function readStorage(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
let cart=readStorage('yabloko-cart',[]),favorites=readStorage('yabloko-favorites',[]);cart=Array.isArray(cart)?cart.filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99&&Number.isFinite(x.price)&&x.price>0):[];favorites=Array.isArray(favorites)?favorites.filter(x=>products.some(p=>p.id===x)):[];
function save(){try{localStorage.setItem('yabloko-cart',JSON.stringify(cart));localStorage.setItem('yabloko-favorites',JSON.stringify(favorites))}catch{}updateCount()}
let page=document.body.dataset.page;let params=new URLSearchParams(location.search);
function brand(){return '<a class="brand" href="index.html" aria-label="APPLE MARKET — главная"><img class="brand-mark" src="assets/apple-market-mark.svg" alt="" width="32" height="34"><span>APPLE MARKET</span></a>'}
function shell(){const nav=[['home','Главная','index.html','home'],['catalog','Каталог','catalog.html','catalog'],['cart','Корзина','cart.html','bag'],['favorites','Избранное','favorites.html','heart'],['chat','Чат','#','chat']];const active=page==='product'?'catalog':page;document.body.innerHTML=`<canvas id="matrix" aria-hidden="true"></canvas><div class="container"><header class="header"><button class="icon-btn top-control" data-open="search-dialog" aria-label="Поиск">${icon('search')}<span class="search-label">Поиск</span></button>${brand()}<div class="header-actions" role="group" aria-label="Тема и меню"><button class="icon-btn theme-toggle" id="theme-toggle" aria-label="Включить тёмную тему" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.2 15.1A8.6 8.6 0 0 1 8.9 3.8a8.6 8.6 0 1 0 11.3 11.3Z" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg></button><button class="icon-btn menu-trigger" data-open="menu-dialog" aria-label="Открыть меню" aria-haspopup="dialog">${icon('menu')}</button></div></header><main id="main"></main></div><footer class="footer"><div class="container"><div class="footer-inner"><div>${brand()}<p>Технологии, которые становятся вашими.</p></div><div><h4>Устройства</h4>${cats.slice(1).map(c=>`<a href="catalog.html?category=${c}">${c}</a>`).join('')}</div><div><h4>Поддержка</h4><span class="footer-label">О магазине</span><span class="footer-label">Доставка и оплата</span><span class="footer-label">Помощь и контакты</span></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} APPLE MARKET</span><span>Демонстрационная витрина · Цены примерные</span><span>Иконки Solar · CC BY 4.0</span></div></div></footer><nav class="dock" aria-label="Основная навигация">${nav.map(([id,label,url,glyph])=>id==='chat'?`<button class="dock-item" data-open="chat-dialog" aria-label="Чат обратной связи">${icon(glyph)}<span>${label}</span></button>`:`<a class="dock-item ${active===id?'active':''}" href="${url}" aria-label="${label}" ${active===id?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${id==='cart'?'<span class="count" id="cart-count" hidden></span>':''}</a>`).join('')}</nav><dialog class="chat" id="chat-dialog" aria-label="Чат обратной связи"><div class="chat-head"><div><strong>APPLE MARKET</strong><small>Помощник по выбору · без оператора</small></div><button class="icon-btn" data-close aria-label="Закрыть чат">${icon('close')}</button></div><div class="messages" id="messages" aria-live="polite"><div class="message">Здравствуйте! Помогу разобраться в устройствах Apple. Что выбираете?</div></div><div class="chat-quick"><button data-question="Помоги выбрать iPhone">iPhone Duo</button><button data-question="Нужен ноутбук для работы">Для работы</button><button data-question="Как оформить заказ?">Как заказать?</button></div><form class="chat-form"><input aria-label="Сообщение помощнику" placeholder="Ваш вопрос…" required maxlength="500"><button aria-label="Отправить">${icon('arrow')}</button></form></dialog><dialog class="search-dialog" id="search-dialog" aria-label="Поиск по каталогу"><div class="dialog-top"><h2>Найдём ваше.</h2><button class="icon-btn" data-close aria-label="Закрыть поиск">${icon('close')}</button></div><input class="search-input" type="search" placeholder="iPhone, MacBook, AirPods…" aria-label="Поиск товаров"><div class="search-results"></div></dialog><dialog class="menu-dialog" id="menu-dialog" aria-label="Меню"><div class="dialog-top"><span class="menu-wordmark">APPLE MARKET</span><button class="icon-btn" data-close aria-label="Закрыть меню">${icon('close')}</button></div><nav><a href="catalog.html">Каталог ${icon('arrow')}</a><a href="about.html">О магазине ${icon('arrow')}</a><a href="delivery.html">Доставка и оплата ${icon('arrow')}</a><a href="support.html">Помощь ${icon('arrow')}</a></nav></dialog><div class="toast" role="status" aria-live="polite"></div>`;updateCount()}
function updateCount(){const el=$('#cart-count');if(el){const n=cart.reduce((s,x)=>s+x.qty,0);el.textContent=n;el.hidden=!n}}
let toastTimer;function toast(t){$('.toast').textContent=t;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),3000)}
function breadcrumbs(title){return `<div class="breadcrumbs"><a href="index.html">Главная</a><span>/</span><span>${escapeHTML(title)}</span></div>`}
function productURL(p){return 'product.html?id='+p.id}
function cardSlides(p,state){return galleryFor(p,state.color).map((src,i)=>`<div class="card-slide" aria-hidden="${i!==state.index}"><img src="assets/${src}" alt="${p.name} — ${p.colors[state.color]}, фото ${i+1}" loading="lazy" width="600" height="600" draggable="false"></div>`).join('')}
function cardDots(p,state){return galleryFor(p,state.color).map((_,i)=>`<button class="photo-dot ${i===state.index?'active':''}" data-card-index="${i}" data-product-id="${p.id}" aria-label="${p.name}: фото ${i+1}" aria-pressed="${i===state.index}"><span></span></button>`).join('')}
function card(p){const state=cardSelections[p.id]||{color:0,index:0};return `<article class="card" data-card-id="${p.id}"><button class="icon-btn favorite ${favorites.includes(p.id)?'selected':''}" data-favorite="${p.id}" aria-label="${favorites.includes(p.id)?'Убрать из избранного':'В избранное'}: ${p.name}" aria-pressed="${favorites.includes(p.id)}">${icon(favorites.includes(p.id)?'heartFill':'heart')}</button><div class="card-image"><div class="card-viewport" data-swipe-card="${p.id}" tabindex="0" role="group" aria-roledescription="карусель" aria-label="Фотографии ${p.name}. Листайте влево и вправо"><div class="card-track" style="transform:translateX(-${state.index*100}%)">${cardSlides(p,state)}</div></div><div class="photo-dots" aria-label="Ракурсы ${p.name}">${cardDots(p,state)}</div></div><a class="card-link" href="${productURL(p)}"><h3>${p.name}</h3></a><div class="card-colors" aria-label="Цвет ${p.name}">${p.colors.map((c,i)=>`<button class="color-dot ${i===state.color?'active':''}" style="--swatch:${colorHex(c)}" data-card-color="${i}" data-product-id="${p.id}" aria-label="${p.name}: ${c}" title="${c}" aria-pressed="${i===state.color}"></button>`).join('')}</div>${p.availability?'<p class="availability">С 23 октября</p>':''}<div class="card-bottom"><span class="price">от ${money(p.price)}</span>${page==='catalog'?`<div class="catalog-buy" data-buy="${p.id}"></div>`:`<button class="add-btn" data-add="${p.id}" aria-label="Добавить ${p.name} в корзину">${icon('plus')}</button>`}</div></article>`}
function home(){return `<section class="hero" aria-label="Баннер iPhone Duo"><div class="hero-copy"><h1>iPhone Duo.<br>Больше мира.</h1><p>Ваш мир. Теперь без границ.</p><a class="pill iridescent" href="product.html?id=iphone-duo">Выбрать Duo ${icon('arrow')}</a></div><div class="hero-visual"><video id="hero-video" muted playsinline loop preload="metadata" poster="assets/iphone-duo-hero-still.jpg" aria-label="iPhone Duo — видео Apple"><source src="assets/iphone-duo-hero.mp4" type="video/mp4"></video></div></section><div class="second-row"><section class="portrait-banner" aria-label="Баннер MacBook Air 3:4"><h2>Лёгкий.<br>С силой M5.</h2><img src="assets/mac-2026.png" alt="MacBook Air с чипом M5" width="980" height="469"><a class="pill iridescent" href="product.html?id=macbook-air">MacBook Air ${icon('up')}</a></section></div><section class="section"><div class="section-title"><h2>Ваша следующая история.</h2><a class="pill outline blue-outline all-devices" href="catalog.html">Все устройства ${icon('arrow')}</a></div><div class="cards">${products.map(card).join('')}</div></section>`}
function catalog(){return `${breadcrumbs('Каталог')}<h1 class="page-heading">Найдите своё.</h1><p class="lead">Устройства Apple для работы, творчества и всего, что между.</p><div class="catalog-layout"><div class="catalog-content"><div class="catalog-search">${icon('search')}<input id="filter-search" type="search" aria-label="Поиск в каталоге" placeholder="Найти устройство"></div><div class="catalog-toolbar"><div class="catalog-tabs" aria-label="Тип устройства"><span class="category-indicator" aria-hidden="true"></span>${cats.map(c=>`<button class="chip ${c===(params.get('category')||'Все')?'active':''}" data-category="${c}" aria-label="${c}" title="${c}">${c==='Все'?'ВСЕ':`<span class="sf-category" style="--symbol:url('${({'iPhone':'assets/sf-iphone.png','Mac':'assets/sf-macbook.png','iPad':'assets/sf-ipad.png','Watch':'assets/sf-applewatch.png','AirPods':'assets/sf-airpods.max.png'})[c]}')" aria-hidden="true"></span>`}</button>`).join('')}</div><div class="sort-wrap"><input type="hidden" id="sort" value="default"><button class="sort-trigger" id="sort-trigger" aria-haspopup="menu" aria-expanded="false" aria-controls="sort-menu"><span id="sort-label">По умолчанию</span>${icon('arrow')}</button><div class="sort-menu" id="sort-menu" role="menu" aria-label="Сортировка" hidden>${[['default','По умолчанию'],['asc','Сначала дешевле'],['desc','Сначала дороже'],['name','По названию']].map(([v,t])=>`<button role="menuitemradio" aria-checked="${v==='default'}" data-sort="${v}"><span>${t}</span><span class="sort-check" aria-hidden="true">✓</span></button>`).join('')}</div></div></div><div class="results-top"><span id="results-count" aria-live="polite"></span></div><div class="cards" id="catalog-cards"></div></div></div><p class="demo-note">Демонстрационный ассортимент. Цены и комплектации требуют подтверждения магазином.</p>`}
let selectedCategory=cats.includes(params.get('category'))?params.get('category'):'Все';
function renderCatalog(){let list=products.filter(p=>(selectedCategory==='Все'||p.category===selectedCategory)&&p.name.toLowerCase().includes($('#filter-search').value.toLowerCase()));const sort=$('#sort').value;if(sort==='asc')list.sort((a,b)=>a.price-b.price);if(sort==='desc')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#results-count').textContent=`Устройств: ${list.length}`;$('#catalog-cards').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>Пока ничего не нашлось</h2><p>Измените запрос или выберите другую категорию.</p><button class="pill outline" data-reset>Сбросить фильтры</button></div>';$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===selectedCategory);b.setAttribute('aria-pressed',String(b.dataset.category===selectedCategory))});requestAnimationFrame(updateCategoryIndicator)}
const cardSelections={};let galleryIndex=0;
let selectedProduct=products.find(p=>p.id===params.get('id')),selectedMemory=0,selectedColor=0;
function productPage(){const p=selectedProduct;if(!p)return `${breadcrumbs('Товар не найден')}<div class="empty"><h1>Такого устройства нет в каталоге</h1><a class="pill" href="catalog.html">Перейти в каталог</a></div>`;document.title=`${p.name} — APPLE MARKET`;return `${breadcrumbs(p.name)}<div class="product-layout">${productGallery(p)}<section class="product-copy"><h1>${p.name}</h1><p>${p.description}</p>${p.availability?`<p class="availability">${p.availability}</p>`:''}${p.memory.length?`<span class="option-label">Память</span><div class="options">${p.memory.map((v,i)=>`<button class="option ${i===0?'active':''}" data-memory="${i}" aria-pressed="${i===0}">${v}</button>`).join('')}</div>`:''}<span class="option-label">Цвет: <span id="color-name">${p.colors[0]}</span></span><div class="options">${p.colors.map((v,i)=>`<button class="option ${i===0?'active':''}" data-color="${i}" aria-pressed="${i===0}">${v}</button>`).join('')}</div>${p.colorImages?'':'<p class="demo-note">Фото иллюстрирует модель; выбранный цвет может отличаться.</p>'}<span class="price" id="product-price">${money(p.price)}</span><button class="pill iridescent" id="product-add">Добавить в корзину ${icon('plus')}</button><p class="demo-note">Примерная цена. Доступность и точная комплектация пока не подтверждены.</p></section></div><section class="specs"><h2>В деталях.</h2><a class="source-link" href="${p.source}" target="_blank" rel="noopener">Характеристики на apple.com ${icon('up')}</a>${Object.entries(p.specs).map(([k,v])=>`<div class="spec-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<details><summary>Как выбрать память?</summary><p>Для обычных приложений и облачного хранения можно начать с базового объёма. Если храните много фото, видео или рабочих файлов на устройстве, рассмотрите больший объём.</p></details><details><summary>Как оформить покупку?</summary><p>Сейчас доступна демонстрационная корзина. Вы можете сохранить список выбранных устройств; оплата и передача заказа магазину ещё не подключены.</p></details></section>`}
function addProduct(p,m=0,c=0){const memory=p.memory[m]||'',color=p.colors[c],key=[p.id,memory,color].join('|'),price=p.price+m*10000;const row=cart.find(x=>x.key===key);if(row){if(row.qty>=99){toast('Максимум 99 устройств в одной позиции');return}row.qty++}else cart.push({key,id:p.id,memory,color,price,qty:1});save();toast(`${p.name} добавлен в корзину`)}
function cartPage(){return `${breadcrumbs('Корзина')}<h1 class="page-heading">Ваш выбор.</h1><div id="cart-body"></div>`}
function renderCart(){if(!cart.length){$('#cart-body').innerHTML='<div class="empty"><h2>Ваша корзина пока пуста</h2><p>Самое интересное ещё впереди. Найдите устройство, которое станет вашим.</p><a class="pill" href="catalog.html">Открыть каталог</a></div>';return}const total=cart.reduce((s,x)=>s+x.price*x.qty,0);$('#cart-body').innerHTML=`<div class="cart-layout"><div>${cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<article class="cart-row"><a href="${productURL(p)}"><img src="assets/${p.image}" alt="${p.name}"></a><div><a href="${productURL(p)}"><h3>${p.name}</h3></a><p>${escapeHTML(x.memory)} ${escapeHTML(x.color)}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Уменьшить количество ${p.name}">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Увеличить количество ${p.name}">+</button></div></div><div><span class="price">${money(x.price*x.qty)}</span><button class="icon-btn" data-remove="${i}" aria-label="Удалить ${p.name}">${icon('close')}</button></div></article>`}).join('')}</div><aside class="summary"><h2>Всё вместе</h2><div class="spec-row"><span>Устройств</span><strong>${cart.reduce((s,x)=>s+x.qty,0)}</strong></div><div class="spec-row"><span>Примерная сумма</span><strong>${money(total)}</strong></div><button class="pill" id="download-order">Сохранить подборку ${icon('arrow')}</button><p>Скачайте список выбранных устройств. Это не заказ: онлайн-оплата и отправка менеджеру пока не подключены.</p></aside></div>`}
function favoritePage(){const list=products.filter(p=>favorites.includes(p.id));return `${breadcrumbs('Избранное')}<h1 class="page-heading">То, что нравится.</h1><p class="lead">Сохранённые устройства — всегда под рукой в этом браузере.</p><div class="cards">${list.length?list.map(card).join(''):'<div class="empty"><h2>Здесь будет ваш личный выбор</h2><p>Нажмите на сердечко рядом с устройством, чтобы сохранить его.</p><a class="pill" href="catalog.html">Посмотреть устройства</a></div>'}</div>`}
function infoPage(type){if(type==='about')return `${breadcrumbs('О магазине')}<div class="info-page"><h1 class="page-heading">Техника — часть жизни.<br>Выбор — её приятная часть.</h1><p class="lead">Собрали Apple в одном месте, чтобы найти своё было проще.</p><div class="info-card"><h2>Начните с того, что важно вам</h2><p>Работа на ходу, творчество, фотографии или любимая музыка. Мы расположили устройства по категориям и оставили главные параметры рядом — без лишнего шума.</p><a class="text-link" href="catalog.html">Знакомиться с коллекцией ${icon('arrow')}</a></div><div class="info-card"><h2>На связи с вашим выбором</h2><p>Сохраните понравившееся в избранное, соберите комплект в корзине или задайте вопрос помощнику. Ваш выбор сохранится в этом браузере.</p><button class="pill outline" data-open="chat-dialog">Задать вопрос ${icon('chat')}</button></div></div>`;if(type==='delivery')return `${breadcrumbs('Доставка и оплата')}<div class="info-page"><h1 class="page-heading">От выбора до встречи.</h1><p class="lead">Здесь появятся условия доставки и оплаты вашего магазина.</p><div class="info-card"><h2>Доставка</h2><p>Город, зоны доставки, сроки и стоимость пока не указаны. Эти условия нужно подтвердить перед запуском продаж.</p></div><div class="info-card"><h2>Оплата</h2><p>Онлайн-оплата пока не подключена. В демонстрационной версии вы можете собрать корзину и сохранить подборку на устройство.</p><a class="text-link" href="cart.html">Перейти к своей подборке ${icon('arrow')}</a></div><div class="info-card"><h2>Гарантия и возврат</h2><p>Условия обслуживания, реквизиты продавца и порядок возврата будут добавлены после подтверждения магазином.</p></div></div>`;return `${breadcrumbs('Помощь')}<div class="info-page"><h1 class="page-heading">Начнём с вопроса.</h1><p class="lead">Поможем сориентироваться в выборе.</p><div class="info-card"><h2>Помощник по каталогу</h2><p>Подскажет подходящую категорию и объяснит, как работают корзина и избранное. Ответы автоматические; живой менеджер пока не подключён.</p><button class="pill iridescent" data-open="chat-dialog">Открыть чат ${icon('chat')}</button></div><details><summary>Цены на сайте окончательные?</summary><p>Нет. Это примерные цены для демонстрации магазина. Ассортимент, стоимость и наличие нужно подтвердить перед началом продаж.</p></details><details><summary>Могу ли я сейчас заказать устройство?</summary><p>Пока можно собрать и скачать подборку. Отправка заказа и приём оплаты не подключены.</p></details><details><summary>Как связаться с магазином?</summary><p>Телефон, адрес и ссылка на мессенджер ещё не добавлены. После подключения здесь появятся контакты менеджера.</p></details></div>`}
function renderSearch(query=''){const matches=products.filter(p=>(p.name+' '+p.category).toLowerCase().includes(query.toLowerCase()));$('.search-results').innerHTML=matches.length?matches.map(p=>`<a class="search-result" href="${productURL(p)}"><img src="assets/${p.image}" alt=""><div>${p.name}<small>${money(p.price)}</small></div>${icon('arrow')}</a>`).join(''):'<p class="muted">Ничего не найдено. Попробуйте «iPhone» или «MacBook».</p>'}
function answer(q){if(/заказ|оплат|купить|достав|цен|налич|менедж|человек|оператор/i.test(q))return 'Это демонстрационная витрина: цены примерные, оплата и связь с менеджером ещё не подключены. Можно добавить устройства в корзину и скачать подборку. Заказ при этом не отправляется.';if(/iphone|айфон|телефон|фото/i.test(q))return 'В каталоге есть складной iPhone Duo и iPhone 18 Pro. У Duo — внутренний экран 7,6″ и чип A20 Pro; Apple указывает начало продаж 23 октября. Для обычного формата посмотрите iPhone 18 Pro.';if(/mac|ноут|работ|уч[её]б/i.test(q))return 'Для повседневной работы и учёбы посмотрите MacBook Air с M5. Если планируете монтаж или сложную графику, перед покупкой стоит уточнить процессор и объём оперативной памяти. Модель находится в разделе MacBook.';if(/музык|науш|airpods|подар/i.test(q))return 'Посмотрите AirPods Pro 3: активное шумоподавление, пространственное аудио и измерение пульса во время тренировок. Модель есть в разделе AirPods.';if(/ipad|планш|рисов/i.test(q))return 'Для чтения, заметок и творчества посмотрите iPad Air. Перед покупкой стилуса или клавиатуры обязательно проверьте совместимость с конкретной моделью.';if(/памят|гб|gb/i.test(q))return 'Объём зависит от ваших файлов: если храните много видео, фото или проектов на устройстве, выбирайте больше памяти. Доступные варианты есть в карточке товара.';if(/привет|здрав/i.test(q))return 'Здравствуйте! Выбираете телефон, ноутбук, планшет или наушники?';return 'Я пока умею отвечать на базовые вопросы о выборе iPhone, MacBook, iPad и AirPods, а также о корзине. Напишите, какое устройство вам нужно. Данные о наличии и контакты магазина ещё не подключены.'}
function sendChat(q){q=q.trim();if(!q)return;const messages=$('#messages');for(const [cls,text]of [['user',q],['',answer(q)]]){const div=document.createElement('div');div.className='message '+cls;div.textContent=text;messages.appendChild(div)}messages.scrollTop=messages.scrollHeight}
