const heroObserver=new IntersectionObserver(entries=>{heroVisible=entries[0].isIntersecting;syncHero()});
function syncHero(){const video=$('#hero-video');if(!video)return;if(motionPreference.matches||!heroVisible||document.hidden||$('dialog[open]')){video.pause()}else{video.muted=true;video.play().catch(()=>{})}}
function initHero(){heroObserver.disconnect();heroVisible=true;const video=$('#hero-video');if(video){heroObserver.observe(video);syncHero()}}
motionPreference.addEventListener('change',syncHero);document.addEventListener('visibilitychange',syncHero);new MutationObserver(syncHero).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});
// A persistent theme shared by every page, applied before styles load.
const themeToggle=$('#theme-toggle');
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';themeToggle.setAttribute('aria-pressed',String(dark));themeToggle.setAttribute('aria-label',dark?'Включить светлую тему':'Включить тёмную тему');const meta=$('meta[name="theme-color"]');if(meta)meta.content=dark?'#121214':'#f4f5f7'}
themeToggle.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('apple-market-theme',document.documentElement.dataset.theme)}catch{}syncTheme()});
addEventListener('storage',e=>{if(e.key==='apple-market-theme'){document.documentElement.dataset.theme=e.newValue==='dark'?'dark':'light';syncTheme()}});syncTheme();
// Hold the selected item, then drag to preview a destination; release to open it.
const dock=$('.dock');let navDrag=null,suppressNavClick=false;
function clearNavDrag(){if(navDrag)clearTimeout(navDrag.timer);navDrag=null;dock.classList.remove('scrubbing');$$('.dock-item').forEach(el=>el.classList.remove('scrub-target'));updateDockIndicator()}
dock.addEventListener('pointerdown',e=>{const item=e.target.closest('.dock-item');if(e.button!==0||!item||!(item.classList.contains('active')||item.getAttribute('aria-expanded')==='true'))return;navDrag={id:e.pointerId,x:e.clientX,y:e.clientY,item,target:item,ready:false};navDrag.timer=setTimeout(()=>{if(!navDrag)return;navDrag.ready=true;dock.setPointerCapture(e.pointerId);dock.classList.add('scrubbing');item.classList.add('scrub-target')},180)});
dock.addEventListener('pointermove',e=>{const d=navDrag;if(!d||d.id!==e.pointerId)return;if(!d.ready){if(Math.hypot(e.clientX-d.x,e.clientY-d.y)<=10)return;clearTimeout(d.timer);d.ready=true;dock.setPointerCapture(e.pointerId);dock.classList.add('scrubbing')}const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('.dock-item');d.target=hit&&dock.contains(hit)?hit:null;$$('.dock-item').forEach(el=>el.classList.toggle('scrub-target',el===d.target));if(d.target)moveDockIndicator(d.target)});
dock.addEventListener('pointerup',e=>{if(!navDrag||navDrag.id!==e.pointerId)return;const {ready,target,item}=navDrag;clearNavDrag();if(ready){suppressNavClick=true;setTimeout(()=>suppressNavClick=false,400);if(target&&target!==item){if(target.dataset.open)openPanel(target.dataset.open);else{const url=new URL(target.href);url.searchParams.set('v','apple-market-18');navigate(url)}}}});
dock.addEventListener('pointercancel',clearNavDrag);dock.addEventListener('lostpointercapture',clearNavDrag);
dock.addEventListener('click',e=>{if(suppressNavClick){e.preventDefault();e.stopPropagation();suppressNavClick=false}},true);
dock.addEventListener('contextmenu',e=>e.preventDefault());

dock.addEventListener('dragstart',e=>e.preventDefault());

// Safari browser chrome already reserves the bottom safe area. Other browsers keep their offset.
const ua=navigator.userAgent;
if(/iPhone|iPad|iPod/.test(ua)&&/Safari/.test(ua)&&!/CriOS|FxiOS|EdgiOS|OPiOS|DuckDuckGo/.test(ua)&&!navigator.standalone&&!matchMedia('(display-mode: standalone)').matches)document.documentElement.classList.add('ios-safari');
document.addEventListener('pointerdown',()=>document.documentElement.classList.remove('keyboard-navigation'),true);
document.addEventListener('keydown',e=>{if(e.key==='Tab')document.documentElement.classList.add('keyboard-navigation')},true);

// Persistent shell, browser history, and route-scoped listeners.
let routeEvents=new AbortController();
const routeNames={index:'home',catalog:'catalog',product:'product',cart:'cart',favorites:'favorites',about:'about',delivery:'delivery',support:'support'};
const scrollPositions=new Map();let currentRoute=location.pathname+location.search;
let catalogState={query:'',sort:'default',category:selectedCategory};
const indicator=document.createElement('span');indicator.className='dock-indicator';indicator.setAttribute('aria-hidden','true');dock.prepend(indicator);
function moveDockIndicator(item){if(!item){indicator.style.opacity='0';return}indicator.style.opacity='1';indicator.style.width=item.offsetWidth+'px';indicator.style.height=item.offsetHeight+'px';indicator.style.transform=`translate3d(${item.offsetLeft}px,${item.offsetTop}px,0)`}
function updateDockIndicator(){moveDockIndicator($('.dock [aria-expanded="true"]')||$('.dock-item.active'))}
new ResizeObserver(updateDockIndicator).observe(dock);
function mountRoute(){initCatalog();initProductGallery();initHero();updateDockIndicator()}
function navigate(input,pop=false){
 const url=new URL(input,location.href);const name=url.pathname.split('/').pop().replace(/\.html$/,'')||'index';const next=routeNames[name];if(!next)return;
 scrollPositions.set(currentRoute,scrollY);
 if(page==='catalog'&&$('#filter-search'))catalogState={query:$('#filter-search').value,sort:$('#sort').value,category:selectedCategory};
 routeEvents.abort();routeEvents=new AbortController();heroObserver.disconnect();$('#hero-video')?.pause();cardDrag=null;
 $$('dialog[open]').forEach(d=>{d.getAnimations().forEach(a=>a.cancel());d.close();delete d.dataset.closing});$('.dock [data-open="chat-dialog"]').setAttribute('aria-expanded','false');
 if(!pop)history.pushState({},'',url);currentRoute=url.pathname+url.search;params=new URLSearchParams(url.search);page=next;document.body.dataset.page=page;
 selectedCategory=params.get('category')||catalogState.category;selectedProduct=products.find(p=>p.id===params.get('id'));selectedMemory=0;selectedColor=0;galleryIndex=0;
 $('#main').getAnimations().forEach(a=>a.cancel());$('#main').innerHTML=page==='home'?home():page==='catalog'?catalog():page==='product'?productPage():page==='cart'?cartPage():page==='favorites'?favoritePage():infoPage(page);
 if(page==='catalog'){$('#filter-search').value=catalogState.query;$('#sort').value=catalogState.sort;$('#sort-label').textContent=({'default':'По умолчанию',asc:'Сначала дешевле',desc:'Сначала дороже',name:'По названию'})[catalogState.sort];$$('[data-sort]').forEach(e=>e.setAttribute('aria-checked',String(e.dataset.sort===catalogState.sort)));renderCatalog()}
 if(page==='cart')renderCart();
 document.title=(page==='product'&&selectedProduct?selectedProduct.name:({home:'Техника Apple',catalog:'Каталог',cart:'Корзина',favorites:'Избранное',about:'О магазине',delivery:'Доставка',support:'Помощь'})[page])+' — APPLE MARKET';
 $$('.dock a').forEach(a=>{const on=new URL(a.href).pathname.split('/').pop()===(page==='product'?'catalog':page==='home'?'index':page)+'.html';a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 mountRoute();window.scrollTo({top:pop?(scrollPositions.get(currentRoute)||0):0,behavior:'instant'});
 if(!motionPreference.matches)$('#main').animate([{opacity:.55,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,easing:'ease-out'});
}
document.addEventListener('click',e=>{if(e.defaultPrevented||e.button>0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest('a[href]');if(!a||a.target||a.hasAttribute('download'))return;const url=new URL(a.href,location.href);if(url.origin!==location.origin||url.hash)return;const name=url.pathname.split('/').pop().replace(/\.html$/,'')||'index';if(!routeNames[name])return;e.preventDefault();navigate(url)});
addEventListener('popstate',()=>navigate(location.href,true));history.scrollRestoration='manual';mountRoute();

// Keep add buttons in sync with the selected configuration and saved cart.
function syncAddButtons(){
 syncCatalogBuy();
 const update=(button,p,m,c)=>{if(!button||!p)return;const memory=p.memory[m]||'',color=p.colors[c];const qty=cart.filter(x=>x.id===p.id&&x.memory===memory&&x.color===color).reduce((n,x)=>n+x.qty,0);const state=p.id+'|'+memory+'|'+color+'|'+qty;if(button.dataset.cartState===state)return;const previous=button.dataset.cartQty;button.dataset.cartState=state;button.dataset.cartQty=qty;button.innerHTML=qty?`<span class="add-quantity">${qty}</span>`:button.id==='product-add'?`Добавить в корзину ${icon('plus')}`:icon('plus');button.setAttribute('aria-label',qty?`${p.name}: в корзине ${qty}. Добавить ещё`:`Добавить ${p.name} в корзину`);if(previous!==undefined&&Number(previous)!==qty&&!motionPreference.matches)button.animate([{transform:'scale(.94)'},{transform:'scale(1.06)',offset:.55},{transform:'scale(1)'}],{duration:360,easing:'cubic-bezier(.2,.85,.25,1)'})};
 $$('[data-add]').forEach(button=>{const p=products.find(p=>p.id===button.dataset.add);update(button,p,0,cardSelections[p?.id]?.color||0)});
 update($('#product-add'),selectedProduct,selectedMemory,selectedColor);
}
new MutationObserver(syncAddButtons).observe($('#main'),{childList:true,subtree:true});
document.addEventListener('click',()=>queueMicrotask(syncAddButtons));
addEventListener('storage',event=>{if(event.key==='yabloko-cart'){try{const saved=JSON.parse(event.newValue||'[]');if(Array.isArray(saved)){cart=saved;updateCount();syncAddButtons();if(page==='cart')renderCart()}}catch{}}});
syncAddButtons();

function syncCatalogBuy(){ $$('[data-buy]').forEach(el=>{const p=products.find(p=>p.id===el.dataset.buy),color=cardSelections[p.id]?.color||0,key=[p.id,p.memory[0]||'',p.colors[color]].join('|'),qty=cart.find(x=>x.key===key)?.qty||0,state=key+'|'+qty;if(el.dataset.state===state)return;el.dataset.state=state;el.innerHTML=qty?`<button data-buy-delta="-1" data-id="${p.id}" aria-label="Уменьшить количество ${p.name}">−</button><span aria-live="polite" aria-label="В корзине ${qty}">${qty}</span><button data-buy-delta="1" data-id="${p.id}" aria-label="Добавить ещё ${p.name}">+</button>`:`<button class="buy-initial" data-buy-delta="1" data-id="${p.id}">В корзину ${icon('plus')}</button>`})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-buy-delta]');if(!b)return;const p=products.find(p=>p.id===b.dataset.id),c=cardSelections[p.id]?.color||0;if(Number(b.dataset.buyDelta)>0)addProduct(p,0,c);else{const key=[p.id,p.memory[0]||'',p.colors[c]].join('|'),row=cart.find(x=>x.key===key);if(row){row.qty--;cart=cart.filter(x=>x.qty>0);save()}}syncAddButtons()});
function updateCategoryIndicator(target){const active=target||$('.catalog-tabs .active'),indicator=$('.category-indicator');if(!active||!indicator)return;indicator.style.width=active.offsetWidth+'px';indicator.style.height=active.offsetHeight+'px';indicator.style.transform=`translate(${active.offsetLeft}px,${active.offsetTop}px)`}
function initCategoryScrub(signal){const bar=$('.catalog-tabs');let drag=null,suppress=false;bar.addEventListener('click',e=>{if(suppress){e.preventDefault();e.stopPropagation();suppress=false}},{capture:true});bar.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-category]');if(e.button!==0||!b)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,target:b,moved:false};bar.setPointerCapture(e.pointerId)});bar.addEventListener('pointermove',e=>{if(!drag)return;if(Math.abs(e.clientX-drag.x)>8)drag.moved=true;if(!drag.moved)return;const b=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-category]');if(b&&bar.contains(b)){drag.target=b;updateCategoryIndicator(b)}});const end=(cancel)=>{if(!drag)return;const d=drag;drag=null;if(bar.hasPointerCapture(d.id))bar.releasePointerCapture(d.id);if(d.moved&&!cancel){suppress=true;d.target.click();selectedCategory=d.target.dataset.category;const u=new URL(location.href);u.searchParams.set('category',selectedCategory);history.replaceState(null,'',u);renderCatalog()}else updateCategoryIndicator()};bar.addEventListener('pointerup',()=>end(false));bar.addEventListener('pointercancel',()=>end(true));addEventListener('resize',()=>updateCategoryIndicator(),{signal});requestAnimationFrame(()=>updateCategoryIndicator())}
